<template>
 <section class="container py-4 committees-page management-page">
  <header class="management-heading"><div class="committee-title"><h1>{{ tr('Comités','Committees') }}</h1><button v-if="canManage && members.length" type="button" class="committee-add-icon" :disabled="busy" :aria-label="committeeEditorOpen ? tr('Cancelar','Cancel') : tr('Crear comité','Create committee')" :title="tr('Crear comité','Create committee')" :aria-expanded="committeeEditorOpen" @click="committeeEditorOpen ? cancel() : openCommitteeEditor()"><span v-if="!committeeEditorOpen" aria-hidden="true">+</span><span v-else class="creation-cancel-label">{{ tr('Cancelar','Cancel') }}</span></button></div><p>{{ tr('Forma equipos con los miembros registrados por el pastor y conserva el acuerdo que les dio origen.','Form teams from the members registered by the pastor and record the decision that established them.') }}</p></header>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p>
  <p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p>
  <template v-else>
   <div class="committee-stats"><span><strong>{{ committees.length }}</strong> {{ tr('comités','committees') }}</span><span><strong>{{ members.length }}</strong> {{ tr('miembros disponibles','available members') }}</span></div>
   <p v-if="!members.length" class="empty-state">{{ tr('Aún no hay miembros registrados. El pastor debe importar o agregar miembros en Miembros antes de formar un comité.','No members are registered yet. The pastor must import or add members in Members before a committee can be formed.') }}</p>
   <details v-if="canManage && members.length" ref="editor" class="management-surface committee-editor" v-show="committeeEditorOpen || editingId !== null" :open="committeeEditorOpen || editingId !== null">
    <summary>{{ editingId ? tr('Editar comité','Edit committee') : tr('Crear comité','Create committee') }}</summary>
    <form @submit.prevent="save"><fieldset :disabled="busy">
     <div class="form-grid"><label>{{ tr('Nombre del comité','Committee name') }} *<input v-model="draft.name" class="form-control" required maxlength="255" /></label><label>{{ tr('Fecha de votación de formación','Formation vote date') }} *<input v-model="draft.formation_voted_on" type="date" class="form-control" :max="today" required /></label><div><label>{{ tr('Minuta de formación','Formation minutes') }} *<select v-model="minutesMode" class="form-select"><option value="system">{{ tr('Buscar junta registrada','Find registered meeting') }}</option><option value="manual">{{ tr('Minuta anterior al sistema','Minutes predating the system') }}</option></select></label><template v-if="minutesMode==='system'"><label><span class="visually-hidden">{{ tr('Buscar por número o fecha','Search by number or date') }}</span><input v-model="minutesSearch" type="search" :placeholder="tr('Buscar por número o fecha','Search by number or date')" class="form-control" /></label><label>{{ tr('Junta que aprobó el comité','Meeting approving the committee') }}<select v-model="draft.formation_meeting_id" class="form-select" required><option value="">{{ tr('Seleccionar minuta','Select minutes') }}</option><option v-for="minute in filteredMinutes" :key="minute.id" :value="minute.id">#{{ minute.minutes_number }} · {{ formatDate(minute.meeting_date) }}</option></select></label><button v-if="draft.formation_meeting_id && auth.canAccess('meetings')" type="button" class="btn btn-outline-secondary mt-2" @click="showMinutes(draft.formation_meeting_id)">{{ tr('Vista rápida de la minuta','Quick minutes preview') }}</button><small v-if="!minutes.length">{{ tr('No hay juntas finalizadas. Para registros anteriores, usa la opción de minuta anterior al sistema.','No completed meetings. For older records, use the minutes predating the system option.') }}</small></template><label v-else>{{ tr('Número de minuta anterior','Earlier minutes number') }}<input v-model="draft.minutes_number" class="form-control" required maxlength="100" :placeholder="tr('Ej. 2025-12','E.g. 2025-12')" /></label></div></div>
     <label>{{ tr('Objetivo · ¿Para qué se forma este comité?','Objective · What is this committee for?') }} *<textarea v-model="draft.objective" class="form-control" rows="3" required maxlength="10000"></textarea></label>
     <section class="member-picker"><div class="picker-heading"><h2>{{ tr('Integrantes','Members') }}</h2><span>{{ draft.member_ids.length }} {{ tr('seleccionados','selected') }}</span></div><label><span class="visually-hidden">{{ tr('Buscar miembros','Search members') }}</span><input v-model="memberSearch" type="search" class="form-control" :placeholder="tr('Nombre o correo','Name or email')" /></label><div class="member-options"><label v-for="member in availableMembers" :key="member.id" class="member-option"><input v-model="draft.member_ids" :value="member.id" type="checkbox" /><span>{{ member.name }}<small>{{ member.email }}</small></span></label><p v-if="!availableMembers.length">{{ tr('No hay coincidencias.','No matches.') }}</p></div><small>{{ tr('Selecciona al menos un miembro. La cantidad se calcula automáticamente.','Select at least one member. The count is calculated automatically.') }}</small></section>
     <p v-if="formError" class="alert alert-danger" role="alert">{{ formError }}</p>
     <p class="muted">{{ tr('Creado por se registra automáticamente con tu cuenta.','Created by is recorded automatically from your account.') }}</p>
     <div class="actions"><button class="btn btn-primary" :disabled="!draft.member_ids.length">{{ busy ? tr('Guardando…','Saving…') : editingId ? tr('Guardar cambios','Save changes') : tr('Crear comité','Create committee') }}</button><button type="button" class="btn btn-outline-secondary" @click="cancel">{{ tr('Cancelar','Cancel') }}</button></div>
    </fieldset></form>
   </details>
   <section class="committee-list"><label><span class="visually-hidden">{{ tr('Buscar comités','Search committees') }}</span><input v-model="search" type="search" class="form-control" :placeholder="tr('Nombre, objetivo o integrante','Name, objective or member')" /></label>
    <p v-if="!filteredCommittees.length" class="empty-state">{{ committees.length ? tr('No hay coincidencias.','No matches.') : tr('Todavía no se han formado comités.','No committees have been formed yet.') }}</p>
    <article v-for="committee in filteredCommittees" :key="committee.id" class="management-surface committee-card"><header><h2>{{ committee.name }}</h2><span class="count-badge">{{ committee.members_count }} {{ tr('integrantes','members') }}</span></header><p class="objective">{{ committee.objective }}</p><dl><div><dt>{{ tr('Votación de formación','Formation vote') }}</dt><dd>{{ formatDate(committee.formation_voted_on) }}</dd></div><div><dt>{{ tr('Minuta','Minutes') }}</dt><dd><button v-if="committee.formation_meeting_id && auth.canAccess('meetings')" type="button" class="minutes-link" @click="showMinutes(committee.formation_meeting_id,true)">#{{ committee.minutes_number }} · {{ tr('Ver PDF','View PDF') }}</button><span v-else>{{ committee.minutes_number }}</span><button v-if="committee.formation_meeting_id && auth.canAccess('meetings')" type="button" class="minutes-link meeting-view-link" @click="showMinutes(committee.formation_meeting_id)">{{ tr('Ver junta','View meeting') }}</button></dd></div><div><dt>{{ tr('Creado por','Created by') }}</dt><dd>{{ committee.creator?.name || tr('Cuenta no disponible','Account unavailable') }}</dd></div></dl><details><summary>{{ tr('Ver integrantes','View members') }}</summary><ul><li v-for="member in committee.members" :key="member.id">{{ member.name }} <small>{{ member.email }}</small></li></ul></details><button v-if="canManage" class="btn btn-outline-secondary" :disabled="busy" @click="editingId===committee.id ? cancel() : edit(committee)" :aria-expanded="editingId===committee.id">{{ editingId===committee.id ? tr('Cancelar','Cancel') : tr('Editar comité','Edit committee') }}</button><section class="committee-results"><header><h3>{{ tr('Resultados del comité','Committee results') }}</h3><span class="count-badge">{{ committee.reports?.length ? tr('Resultados recibidos','Results received') : tr('Pendiente de informe','Awaiting report') }}</span></header><p v-if="!committee.reports?.length" class="muted">{{ tr('Cuando el comité termine su trabajo, carga aquí su informe.','When the committee finishes its work, upload its report here.') }}</p><ul v-else class="report-list"><li v-for="report in committee.reports" :key="report.id"><div><strong>{{ report.title }}</strong><small>{{ report.original_name }} · {{ formatSize(report.size) }}</small><small>{{ tr('Cargado por','Uploaded by') }} {{ report.uploader?.name || '—' }} · {{ new Date(report.created_at).toLocaleString(ui.locale) }}</small></div><div class="record-actions"><span class="record-actions-label">{{ tr('Acciones','Actions') }}</span><div class="record-actions-buttons"><button type="button" class="btn btn-outline-secondary" @click="showReport(committee,report)">{{ tr('Ver informe','View report') }}</button><button type="button" class="btn btn-outline-secondary" :disabled="downloading===report.id" @click="downloadReport(committee,report)">{{ tr('Descargar','Download') }}</button></div></div></li></ul><FormSection v-if="auth.can('committees.results')" :busy="uploading===committee.id" :title="tr('Cargar informe de resultados','Upload results report')"><form @submit.prevent="uploadReport(committee,$event)"><fieldset :disabled="uploading===committee.id"><label>{{ tr('Título del informe','Report title') }}<input class="form-control" name="title" required maxlength="255" /></label><label>{{ tr('Archivo del informe','Report file') }}<input class="form-control" type="file" name="file" accept=".doc,.docx,.xlsx,.csv,.pdf" required /></label><small>Word (.doc, .docx), Excel (.xlsx), CSV, PDF · {{ tr('Máximo 20 MB por archivo','Maximum 20 MB per file') }}</small><p v-if="reportErrors[committee.id]" class="alert alert-danger" role="alert">{{ reportErrors[committee.id] }}</p><button class="btn btn-primary">{{ uploading===committee.id ? tr('Cargando…','Uploading…') : tr('Guardar informe','Save report') }}</button></fieldset></form></FormSection></section></article>
   </section>
  </template>
  <Teleport to="body"><div v-if="previewOpen" class="committee-preview-backdrop" @click.self="closePreview"><section ref="previewDialog" class="committee-preview" role="dialog" aria-modal="true" aria-labelledby="committee-preview-title" tabindex="-1" @keydown.esc="closePreview" @keydown.tab="trapPreviewFocus"><header><h2 id="committee-preview-title">{{ selectedReport ? selectedReport.report.title : tr('Vista rápida de la minuta','Quick minutes preview') }}</h2><button type="button" class="btn btn-outline-secondary" @click="closePreview">{{ tr('Cerrar','Close') }}</button></header><button v-if="selectedReport" class="btn btn-outline-secondary" :disabled="downloading===selectedReport.report.id" @click="downloadReport(selectedReport.committee,selectedReport.report)">{{ tr('Descargar original','Download original') }}</button><p v-if="previewLoading" role="status">{{ tr('Cargando…','Loading…') }}</p><p v-else-if="previewError" role="alert">{{ previewError }}</p><template v-else-if="previewPdfUrl"><a v-if="!selectedReport" :href="previewPdfUrl" :download="`minuta-${previewMeetingId}.pdf`" class="btn btn-outline-secondary">{{ tr('Descargar PDF','Download PDF') }}</a><iframe class="minutes-pdf" :src="previewPdfUrl" :title="selectedReport?.report.title || tr('PDF de la minuta seleccionada','Selected minutes PDF')"></iframe></template><template v-else-if="reportPreview"><p v-if="reportPreview.type==='unsupported'">{{ tr('Este formato no tiene vista previa. Descarga el original o carga una versión PDF o DOCX.','Preview is unavailable for this format. Download the original or upload a PDF or DOCX version.') }}</p><template v-else-if="reportPreview.type==='table'"><p class="muted">{{ tr('Vista limitada a 10 hojas, 200 filas y 30 columnas por hoja. Descarga el original para ver todos los datos. Las fórmulas no se recalculan.','Preview limited to 10 sheets, 200 rows and 30 columns per sheet. Download the original for all data. Formulas are not recalculated.') }}</p><section v-for="(sheet,index) in reportPreview.sheets" :key="index"><h3>{{ sheet.name }}</h3><div class="report-table"><table><tbody><tr v-for="(row,r) in sheet.rows" :key="r"><td v-for="(cell,c) in row" :key="c">{{ cell }}</td></tr></tbody></table></div></section></template><template v-else><p class="muted">{{ tr('Vista de texto. Descarga el original para conservar el formato y las imágenes.','Text preview. Download the original for formatting and images.') }}</p><pre class="report-text">{{ reportPreview.text }}</pre></template></template><template v-else-if="preview"><p>{{ formatDate(preview.meeting_date) }} · {{ preview.location || '—' }}</p><p v-if="!preview.summary_public && !auth.can('meetings.manage')">{{ tr('Esta minuta es privada.','These minutes are private.') }}</p><MeetingOverview v-else :meeting="preview" :locale="ui.locale" /></template></section></div></Teleport>
 </section>
</template>
<script setup>
import FormSection from "./FormSection.vue"
import {computed,ref,onMounted,onUnmounted,nextTick,watch} from 'vue'
import {meetingApi} from '../services/meetingApi'
import MeetingOverview from './MeetingOverview.vue'
import {apiClient} from '../services/authApi'
import {useAuthStore} from '../stores/authStore'
import {useUiStore} from '../stores/uiStore'
import '../styles/clerk-management.css'
const auth=useAuthStore(),ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const committees=ref([]),members=ref([]),minutes=ref([]),minutesMode=ref('system'),minutesSearch=ref(''),loading=ref(true),busy=ref(false),error=ref(''),formError=ref(''),notice=ref(''),search=ref(''),memberSearch=ref(''),editingId=ref(null),editor=ref(null)
const blank=()=>({name:'',objective:'',formation_voted_on:'',minutes_number:'',formation_meeting_id:'',member_ids:[],revision:1}),draft=ref(blank())
const selectedReport=ref(null),reportPreview=ref(null)
const committeeEditorOpen=ref(false)
const uploading=ref(null),downloading=ref(null),reportErrors=ref({}),previewPdfUrl=ref(''),previewMeetingId=ref(null)
const formatSize=size=>size<1024*1024?`${Math.ceil(size/1024)} KB`:`${(size/1024/1024).toFixed(1)} MB`
async function uploadReport(committee,event){if(uploading.value)return;const form=event.target,body=new FormData(form),file=body.get('file');if(file.size>20*1024*1024){reportErrors.value[committee.id]=tr('El archivo supera 20 MB.','File exceeds 20 MB.');return}uploading.value=committee.id;reportErrors.value[committee.id]='';try{const {data}=await apiClient.post(`/committees/${committee.id}/reports`,body);committee.reports=[data,...(committee.reports||[])];form.reset();notice.value=tr('Informe de resultados guardado.','Results report saved.')}catch(e){reportErrors.value[committee.id]=message(e)}finally{uploading.value=null}}
async function downloadReport(committee,report){downloading.value=report.id;error.value='';try{const {data}=await apiClient.get(`/committees/${committee.id}/reports/${report.id}/download`,{responseType:'blob'});const url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=report.original_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{error.value=tr('No se pudo descargar el informe.','Unable to download report.')}finally{downloading.value=null}}
function releasePdf(){if(previewPdfUrl.value)URL.revokeObjectURL(previewPdfUrl.value);previewPdfUrl.value=''}
const previewOpen=ref(false),previewLoading=ref(false),previewError=ref(''),preview=ref(null),previewDialog=ref(null)
let previewVersion=0,previewOpener=null,originalOverflow=''
async function showMinutes(id,pdf=false){selectedReport.value=null;reportPreview.value=null;const version=++previewVersion;releasePdf();previewMeetingId.value=id;previewOpener=document.activeElement;originalOverflow=document.body.style.overflow;document.body.style.overflow='hidden';previewOpen.value=true;previewLoading.value=true;previewError.value='';preview.value=null;await nextTick();previewDialog.value?.focus();try{if(pdf){const blob=await meetingApi.downloadMeetingSummary(id,ui.locale);if(version===previewVersion)previewPdfUrl.value=URL.createObjectURL(blob)}else{const {data}=await apiClient.get(`/meetings/${id}`);if(version===previewVersion)preview.value=data}}catch(e){if(version===previewVersion)previewError.value=e.response?.data instanceof Blob ? tr('No se pudo abrir el PDF. Verifica el acceso a esta minuta.','Unable to open the PDF. Check access to these minutes.') : message(e)}finally{if(version===previewVersion)previewLoading.value=false}}
async function showReport(committee,report){
 const version=++previewVersion;releasePdf();selectedReport.value={committee,report};reportPreview.value=null;preview.value=null;
 previewOpener=document.activeElement;originalOverflow=document.body.style.overflow;document.body.style.overflow='hidden';previewOpen.value=true;previewLoading.value=true;previewError.value='';await nextTick();previewDialog.value?.focus();
 try{const pdf=report.original_name.toLowerCase().endsWith('.pdf');const {data}=await apiClient.get(`/committees/${committee.id}/reports/${report.id}/preview`,{responseType:pdf?'blob':'json'});if(version!==previewVersion)return;if(pdf)previewPdfUrl.value=URL.createObjectURL(data);else reportPreview.value=data}
 catch{if(version===previewVersion)previewError.value=tr('No se pudo abrir la vista previa. Puedes descargar el original.','Unable to preview. You can download the original.')}
 finally{if(version===previewVersion)previewLoading.value=false}
}
function closePreview(){previewVersion++;releasePdf();previewOpen.value=false;document.body.style.overflow=originalOverflow;previewOpener?.focus()}
function trapPreviewFocus(event){const elements=previewDialog.value?.querySelectorAll('button, a[href], select, input, textarea, [tabindex="0"]');if(!elements?.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey && (document.activeElement===first || document.activeElement===previewDialog.value)){event.preventDefault();last.focus()}else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first.focus()}}
onUnmounted(()=>{releasePdf();if(previewOpen.value)document.body.style.overflow=originalOverflow;previewVersion++})
const canManage=computed(()=>auth.can('committees.manage'))
const now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`
const matches=(value,query)=>value.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())
const availableMembers=computed(()=>members.value.filter(m=>matches(`${m.name} ${m.email}`,memberSearch.value)))
const filteredMinutes=computed(()=>minutes.value.filter(m=>m.id===draft.value.formation_meeting_id || matches(`${m.minutes_number} ${m.meeting_date} ${formatDate(m.meeting_date)}`,minutesSearch.value)))
const filteredCommittees=computed(()=>committees.value.filter(c=>matches([c.name,c.objective,...c.members.map(m=>m.name)].join(' '),search.value)))
const formatDate=value=>value ? new Date(value.slice(0,10)+'T12:00:00').toLocaleDateString(ui.locale) : '—'
const message=e=>Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||tr('No se pudo guardar.','Unable to save.')
let generation=0
async function load(){const version=++generation;loading.value=true;error.value='';try{const {data}=await apiClient.get('/committees');if(version!==generation)return;committees.value=data.committees;members.value=data.members;minutes.value=data.minutes}catch(e){if(version===generation)error.value=message(e)}finally{if(version===generation)loading.value=false}}
function cancel(){committeeEditorOpen.value=false;editingId.value=null;draft.value=blank();minutesMode.value='system';minutesSearch.value='';memberSearch.value='';formError.value='';if(editor.value)editor.value.open=false}
async function openCommitteeEditor(){cancel();committeeEditorOpen.value=true;await nextTick();editor.value?.scrollIntoView({behavior:'smooth',block:'start'})}
async function edit(c){draft.value={name:c.name,objective:c.objective,formation_voted_on:c.formation_voted_on.slice(0,10),minutes_number:c.minutes_number,formation_meeting_id:c.formation_meeting_id || '',member_ids:c.members.map(m=>m.id),revision:c.revision};minutesMode.value=c.formation_meeting_id?'system':'manual';minutesSearch.value='';editingId.value=c.id;formError.value='';notice.value='';memberSearch.value='';await nextTick();editor.value.open=true;editor.value.scrollIntoView({behavior:'smooth',block:'start'})}
async function save(){if(busy.value || !canManage.value)return;busy.value=true;formError.value='';notice.value='';try{await apiClient[editingId.value?'patch':'post'](editingId.value?`/committees/${editingId.value}`:'/committees',{...draft.value,formation_meeting_id:minutesMode.value==='system'?draft.value.formation_meeting_id:null,minutes_number:minutesMode.value==='manual'?draft.value.minutes_number:null});cancel();await load();notice.value=tr('Comité guardado.','Committee saved.')}catch(e){formError.value=message(e)}finally{busy.value=false}}
watch(()=>draft.value.formation_meeting_id,id=>{const minute=minutes.value.find(m=>m.id===id);if(minute && minutesMode.value==='system' && !draft.value.formation_voted_on)draft.value.formation_voted_on=minute.meeting_date.slice(0,10)})
watch(()=>auth.contextKey,()=>{cancel();committees.value=[];members.value=[];load()})
onMounted(load)
</script>
<style scoped>
.committee-title{display:flex;align-items:center;gap:10px}.committee-title h1{margin:0}.committee-add-icon{display:inline-flex;align-items:center;justify-content:center;width:32px;height:32px;padding:0;border:0;background:transparent;color:#1f6f5c;border-radius:8px;font-size:24px;line-height:1;flex:none}.committee-add-icon:has(.creation-cancel-label){width:auto}.creation-cancel-label{font-size:13px}.committee-add-icon:focus-visible{outline:3px solid #85b9a6;outline-offset:3px}
.meeting-view-link{display:block;margin-top:8px}.report-text{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}.report-table{max-width:100%;overflow:auto;max-height:55dvh;margin:12px 0}.report-table td{border:1px solid #dfe6e1;padding:8px;min-width:100px;max-width:320px;overflow-wrap:anywhere}.minutes-link{border:0;padding:0;background:none;color:#1f6f5c;text-decoration:underline;text-align:left;width:auto}.minutes-pdf{display:block;width:100%;height:65dvh;border:1px solid #dfe6e1;margin-top:12px}.committee-results{border-top:1px solid #dde6df;margin-top:20px;padding-top:16px}.committee-results h3{font-size:14px;margin:0}.committee-results form{margin-top:12px}.report-list{list-style:none;padding:0}.report-list li{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:start;gap:20px;padding:16px;border:1px solid #dce5df;border-radius:8px;background:#fff}.record-actions{border-left:1px solid #dce5df;padding-left:20px}.record-actions-label{display:block;font-size:11px;color:#66776d;margin-bottom:8px}.record-actions-buttons{display:flex;gap:8px;flex-wrap:wrap}.record-actions-buttons .btn{margin:0}.report-list li>div:first-child{align-self:center}@media(max-width:700px){.report-list li{grid-template-columns:1fr;gap:12px}.record-actions{border-left:0;border-top:1px solid #dce5df;padding:12px 0 0}.record-actions-buttons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.record-actions-buttons .btn{width:100%}}.report-list li>div{min-width:0;overflow-wrap:anywhere}.committee-preview-backdrop{position:fixed;inset:0;z-index:2000;background:rgba(12,30,22,.5);display:flex;align-items:center;justify-content:center;padding:16px}.committee-preview{background:white;color:#263c30;border-radius:12px;padding:20px;width:min(760px,100%);max-height:90dvh;overflow:auto;box-shadow:0 20px 60px #0003}.committee-preview header{display:flex;justify-content:space-between;align-items:center;gap:16px}.committees-page{min-width:0}.committee-stats{display:flex;flex-wrap: